package com.focusflow.api.controller; import com.focusflow.api.dto.ApiDtos.*; import com.focusflow.api.service.AuthService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/auth") public class AuthController {final AuthService auth;public AuthController(AuthService a){auth=a;} @PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) Auth register(@Valid @RequestBody Register r){return auth.register(r);}@PostMapping("/login") Auth login(@Valid @RequestBody Login r){return auth.login(r);} }
